import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Pick-a-Pic: An Open Dataset of User Preferences for Text-to-Image Generation","description":"","frontmatter":{"title":"Pick-a-Pic: An Open Dataset of User Preferences for Text-to-Image Generation","arxiv":"2305.01569","date":"2023-05-02","authors":"Yuval Kirstain, Adam Polyak, Uriel Singer, Shahbuland Matiana, Joe Penna, Omer Levy","categories":"cs.CV, cs.AI","topics":"后训练与强化学习, 人类偏好数据集, 奖励模型","outline":[2,2]},"headers":[],"relativePath":"papers/2305.01569.md","filePath":"papers/2305.01569.md","lastUpdated":null}'),e={name:"papers/2305.01569.md"};function l(i,s,r,m,c,o){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="pick-a-pic-an-open-dataset-of-user-preferences-for-text-to-image-generation" tabindex="-1">Pick-a-Pic: An Open Dataset of User Preferences for Text-to-Image Generation <a class="header-anchor" href="#pick-a-pic-an-open-dataset-of-user-preferences-for-text-to-image-generation" aria-label="Permalink to &quot;Pick-a-Pic: An Open Dataset of User Preferences for Text-to-Image Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2305.01569" target="_blank" rel="noreferrer">2305.01569</a></td></tr><tr><td><strong>提交日期</strong></td><td>2023-05-02（v2 修订于 2023-11-23）</td></tr><tr><td><strong>作者</strong></td><td>Yuval Kirstain, Adam Polyak, Uriel Singer, Shahbuland Matiana, Joe Penna, Omer Levy（Tel Aviv University / Stability AI）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>造一个真实可用的文生图网页应用，把用户自愿留下的 58 万条二选一偏好攒成公开数据集，再用 InstructGPT 式 reward 目标微调 CLIP-H 得到 PickScore，在预测用户偏好上拿到 70.5%，高于人类专家标注者的 68.0%。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/post-training-rl">后训练与强化学习</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本与口径说明</p><p>本文按 <strong>v2</strong>（2023-11-23）的 HTML 全文撰写。注意论文内部存在一处口径不一致：§2 开头写数据集&quot;包含超过 500,000 条样本与 35,000 个不同 prompt&quot;，而同节&quot;Statistics&quot;小节给出的实验用版本是 <strong>583,747 条训练样本、37,523 个训练 prompt、4,375 名用户</strong>，另有验证/测试各 500 条。作者同时说明网页应用累计已收到 <strong>968,965 条排序、66,798 个 prompt、6,394 名用户</strong>，论文实验用的是一个经 NSFW 过滤、尚未同步到最新的快照。下文一律以&quot;Statistics&quot;小节的数字为准。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>2023 年初文生图模型的评测处在一个尴尬状态：主流指标 FID 在 MS-COCO 上算出来的排名，跟人真正喜欢哪张图基本没关系。原因不难理解，FID 度量的是生成图像集合与真实照片集合在 Inception 特征空间里的分布距离，它<strong>不看 prompt</strong>，也不针对单张图打分。而用户真正在做的事情是：写一句自己想象出来的东西，从模型吐出的若干张图里挑一张最接近脑子里那个画面的。这两件事之间没有必然联系。</p><p>问题的第二层是数据。要训练一个能替代人类打分的评分函数，需要大规模成对偏好标注。当时这类数据基本只有公司内部有（OpenAI、Midjourney 这些手里握着真实用户交互日志），学界拿不到。已有的公开尝试规模都不大：Simulacra Aesthetic Captions 收了近 20 万条<strong>绝对</strong>美学评分（而不是成对比较）；Lee 等人用模板 prompt（比如&quot;[数字] 只狗&quot;）合成了 3 万条众包好坏判断；ImageReward 从 DiffusionDB 里选 prompt 和图，请众包工人按预设标准打分，收了 136,892 条来自 8,878 个 prompt 的样本，且当时未公开发布数据集。</p><p>Pick-a-Pic 要解决的是这一整套：一个真实用户会主动来用的产品、一份公开的偏好数据、一个比 FID 更靠谱的评测指标，以及顺带演示这个指标怎么直接用来提升生成质量。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>绝对评分路线（SAC / LAION-Aesthetic）</strong>：让标注者给单张图打 1–10 分，好处是标注简单、可以堆量。问题是绝对分数与 prompt 无关，一个漂亮但完全跑题的图会拿高分。论文的实验直接量化了这一点：LAION 美学预测器在 Pick-a-Pic 测试集上的准确率是 <strong>56.8</strong>，而随机分类器也是 <strong>56.8</strong> ——美学分在预测&quot;用户会选哪张&quot;这件事上等同于瞎猜。这是本文最有说服力的一个数据点，也是任何用美学分做 headline 指标的工作都必须先回答的问题。</p><p><strong>众包成对标注路线（ImageReward、Lee et al.）</strong>：数据是成对的、与 prompt 绑定的，比绝对评分合理。但众包工人没有内在动机，也不知道原始 prompt 作者到底想要什么，所以研究者必须写一套评判准则让工人照着执行——这实际上把&quot;人类偏好&quot;替换成了&quot;研究者定义的质量标准&quot;。</p><p><strong>社区日志爬取路线（HPS v1）</strong>：Wu 等人从 StabilityAI 的 Discord 频道爬了约 25,000 条人类评分（涉及约 10 万张图），用与 InstructGPT 类似的目标训了 Human Preference Score。数据来自真实用户，但规模有限，且分布高度偏向那一个 Discord 社群的口味。</p><p>作者对这三条路线的定位很清楚：Pick-a-Pic 的数据量比 HPS 和 ImageReward 用的数据大<strong>五倍以上</strong>，且来自有真实生成意图的用户。作者也诚实地承认，PickScore 在 Pick-a-Pic 上赢过 HPS 和 ImageReward，可能来自实现差异（模型大小、backbone、超参）、数据规模差异或数据分布差异，他们没有把这几个因素隔离开，把这件事留给了后续工作。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>如果你在 2023 年初想要一份大规模的真实文生图偏好数据，第一个念头一定是众包。但众包立刻撞上一个哲学问题：偏好是谁的偏好？一个被雇来打标的人看到 prompt &quot;森林里的废墟，照片&quot;和两张图，他能判断哪张更好看，但他判断不了<strong>写这句 prompt 的人脑子里那个废墟长什么样</strong>。这个信息只存在于原作者头脑里。</p><p>顺着这条思路，唯一的出路是让<strong>真正想生成图的人</strong>在生成的当下留下偏好。那就必须做一个产品，而不是一个标注任务。产品要免费、要好用、要能吸引人从 Twitter / Facebook / Discord / Reddit 上过来反复用。</p><p>做产品又带来新问题：交互形式怎么设计才既不打断创作流、又能拿到高质量标注。作者做了 pilot，试了三种：4 张图不许平局、2 张图不许平局、2 张图允许平局。最后一种在<strong>用户参与度</strong>和<strong>标注者间一致性</strong>两项上都最好。这个选择很关键——不许平局会逼用户在两张差不多的图之间瞎选，噪声直接进数据；4 张图则认知负担太重。</p><p>第三个问题是防滥用。免费的图像生成 API 一定会被薅。对策是分层的：Gmail 或 Discord 账号认证、监控行为日志并封禁生成 NSFW 内容/同时开多个实例/点击速度快得不合理的用户、NSFW 词表拦截、每人 1000 次交互上限并周期性提高。</p><p>最后一个问题：拿到数据之后训什么。NLP 那边现成的答案是 InstructGPT 的 reward model 目标。把它搬到图像上只需要一个能同时吃 prompt 和图的打分函数——CLIP 天然就是。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>真实用户之所以是比雇佣标注者更好的标注来源，不是因为他们更专业，而是因为<strong>只有他们知道自己想要什么</strong>。一旦承认这一点，&quot;人类专家准确率&quot;就不再是天花板而只是一个参照系：模型可以通过学到大量用户的平均倾向，超过一个不知道原始意图的旁观者。剩下的工程问题只是把一个免费好用的产品做出来，让数据自己长出来。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据采集</strong>。用户在网页应用里写一句 prompt，拿到两张图；选出更喜欢的那张，或标记平局；被拒绝的那张立刻被一张新生成的图替换，流程重复，直到用户改 prompt。图由多个 backbone 生成：Stable Diffusion 2.1、Dreamlike Photoreal 2.0、以及 Stable Diffusion XL 的若干变体，并且<strong>采样时随机化 classifier-free guidance 尺度</strong>。这个设计让数据集天然覆盖了&quot;同一模型不同 CFG&quot;的对比，后面直接支撑了模型选择实验。</p><p><strong>划分</strong>。先采 1000 个 prompt，保证每个 prompt 来自不同用户；随机对半切成验证集与测试集，每个 prompt 只保留一条样本；训练集则是所有不与验证/测试共享 prompt 的样本。这保证了三个划分之间 prompt 不重叠，且验证/测试不会被某个高频 prompt 或某个高频用户主导。</p><p><strong>PickScore 模型</strong>。沿用 CLIP 结构：给定 prompt <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> 与图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span>，</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span> 是 CLIP 学到的标量温度。</p><p><strong>目标函数</strong>。输入是打分函数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span>、prompt <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span>、两张图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、以及偏好分布向量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">]</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 或平局时 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mclose">]</span></span></span></span>）。先把两个分数 softmax 归一化得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span>，再最小化 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span> 的 KL 散度：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.7068em;vertical-align:-1.2798em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.156em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">exp</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">exp</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2798em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.0788em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8011em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;">(</span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose delimcenter" style="top:0em;">)</span></span></span></span></span></span></p><p>一个容易被忽略但很重要的细节：由于大量样本来自同一个 prompt，batch 内 reduce 时用了<strong>按 prompt 频率的倒数加权</strong>，防止模型过拟合到少数高频 prompt。</p><p><strong>训练</strong>。在 Pick-a-Pic 训练集上微调 OpenCLIP 的 CLIP-H：4,000 步、learning rate 3e-6、总 batch size 128、warmup 500 步后线性衰减，8 张 A100 上不到一小时跑完。作者明说没做超参搜索。模型选择方式是每 100 步在验证集（不允许平局的版本）上评一次准确率，留最好的 checkpoint。</p><p><strong>评测协议</strong>。因为有平局，准确率被改造过：预测与用户标签一致得 1 分，标签与预测中恰好有一个是平局得 0.5 分，其余 0 分。每个模型都需要一个平局阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span>：当 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 时预测平局。这个阈值是<strong>在验证集上逐模型调出来的</strong>（人类专家不调，直接允许他们选平局）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>上面 §5 给出的 KL 目标就是本文唯一的形式化部分，值得多说一句它的 intuition。当没有平局时（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">]</span></span></span></span>），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pref</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，也就是标准的二分类交叉熵，等价于把 Bradley–Terry 模型的负对数似然写在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span> 上。平局的价值在于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mclose">]</span></span></span></span> 时目标变成把两个分数<strong>推到相等</strong>，而不是随便选一个方向推。如果强行把平局当成某一侧的胜利，模型会在大量&quot;其实差不多&quot;的样本上收到互相抵消的梯度，这正是 pilot 里&quot;不许平局&quot;方案表现差的形式化解释。</p><p>作者还试过一个更接近 CLIP 原始对比目标的变体，把 batch 内其余样本当作 in-batch negatives：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1461em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">p</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8991em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.7068em;vertical-align:-1.2798em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.156em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1864em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.954em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">exp</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8309em;"><span style="top:-2.4231em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.0448em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.413em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">exp</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2798em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>预期是这样能更好保留 CLIP 的通用能力，实测反而只有 <strong>65.2</strong> 的测试准确率，明显低于主目标的 70.5。这说明把偏好学习和检索式对比学习混在一起会稀释偏好信号。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：PickScore 能不能预测用户偏好？</strong> 在 Pick-a-Pic 测试集上，随机 56.8、LAION 美学预测器 56.8、CLIP-H 60.8、ImageReward 61.1、HPS 66.7、人类专家 68.0、<strong>PickScore 70.5（±0.142）</strong>。作者用了&quot;superhuman&quot;这个词，但同时给出了它的确切含义：产生 ground truth 的是<strong>真实用户</strong>（有想法、有原始意图），而被用来测量人类表现的是<strong>不知道原始语境的标注者</strong>。所以&quot;超人&quot;意味着模型能超过一个对用户意图一无所知的旁观者，不意味着它超过了写下 prompt 的那个人。另外值得单独记一笔：人类专家 68.0 相对随机 56.8 只高 11.2 个点，说明这个任务对人本身就很难。</p><p><strong>问题二：PickScore 能不能替代 FID 做模型评测？</strong> 作者在对 FID 最有利的设定下测：从 MS-COCO 验证集随机取 100 条 caption，用 9 个模型生成（SD 1.5 / SD 2.1 / Dreamlike Photoreal 2.0 各配 CFG 3、6、9），请人类专家对 9 张图排序（可平局），诱导出成对偏好；再分别用 FID 和 PickScore 重做同一轮&quot;标注&quot;。结果 PickScore 与人类的相关性是 <strong>0.917</strong>，FID 是 <strong>−0.900</strong>——不是零相关而是强负相关。作者的解释是 CFG 尺度这个混杂变量：大 guidance 让图更鲜艳讨喜但偏离 MS-COCO 真实照片的分布，于是 FID 变差。</p><p><strong>问题三：换一个更可信的评测程序还成立吗？</strong> 前一个实验用的是雇佣标注者。这里换成真实用户偏好：取全部 14,000 条对应 Pick-a-Pic 测试集 prompt 的真实偏好，覆盖 45 个&quot;模型&quot;（4 个 backbone × 不同 guidance 尺度），算 Elo 分；再用各个自动指标替换真实偏好重算 Elo。因为 Elo 是迭代的，重复 50 次随机打乱取均值与标准差。相关性：PickScore <strong>0.790±0.054</strong>、HPS <strong>0.670±0.071</strong>、ImageReward <strong>0.492±0.086</strong>、CLIP-H <strong>0.313±0.075</strong>。</p><p><strong>问题四：能不能直接用来提升生成？</strong> 用 Dreamlike Photoreal 2.0、CFG 7.5，对 100 个测试 prompt 各生成 100 张图（5 个初始噪声 × 20 个 prompt 模板，模板包含空模板与&quot;breathtaking [prompt]. award-winning, professional, highly detailed&quot;这类）。人类评委比较 PickScore 选出的图与其他函数选出的图，PickScore 的胜率：对随机种子 + 空模板 <strong>71.4%</strong>、对随机模板 <strong>82.0%</strong>、对美学分 <strong>85.1%</strong>、对 CLIP-H <strong>71.3%</strong>。交叉验证性质的两个数字：PickScore 的选择在 <strong>68.5%</strong> 的 prompt 上美学分高于 CLIP-H 的选择；PickScore 的选择在 <strong>90.5%</strong> 上 CLIP-H 文本对齐分高于美学分选出的图。也就是说 PickScore 同时兼顾了两边，而单一维度的打分器各偏一头。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：文生图评测的核心缺口是缺一份大规模、公开、来自真实用户的成对偏好数据。作者做了一个免费网页应用，让用户在生成过程中顺手留下&quot;喜欢哪张&quot;的判断，攒出 Pick-a-Pic。用 InstructGPT 式的 KL 偏好目标微调 CLIP-H 得到 PickScore，在 Pick-a-Pic 测试集上 70.5% 超过不知情的人类标注者的 68.0%。PickScore 与真实用户 Elo 的相关性 0.790，明显高于 HPS 0.670、ImageReward 0.492、CLIP-H 0.313，而 FID 在 MS-COCO 上与人类判断呈 −0.900 的强负相关。用 PickScore 从 100 张候选里选一张，人类偏好它的比例对各个 baseline 都在 71% 以上。</p><p><strong>3 句话版</strong>：真实用户的偏好比雇佣标注者的偏好更接近&quot;文生图到底要什么&quot;，因为只有用户知道自己 prompt 背后的意图。基于这一点收集的 58 万条偏好训出的 PickScore，在偏好预测、模型排序、样本重排三件事上都明显强于 FID、CLIP 和当时的同期偏好模型。LAION 美学预测器在这个任务上等同于随机猜测（都是 56.8），这一条比任何正面结果都更值得记住。</p><p><strong>1 句话版</strong>：把标注任务变成产品，让有真实生成意图的用户自己产生 ground truth，从而得到一个比 FID 与美学分都可靠得多的文生图偏好评分函数。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的假设是：<strong>Pick-a-Pic 测试集上的准确率能代表&quot;人类对文生图的偏好&quot;这一普遍量</strong>。这个假设一旦不成立，70.5 vs 68.0 的对比与&quot;推荐用 PickScore 评测未来所有文生图模型&quot;的建议就同时垮掉。</p><p>它在实践中很可能不成立，理由有三条。第一，训练集与测试集来自<strong>同一个应用、同一批自选加入的用户、同一组 backbone</strong>（SD 2.1 / Dreamlike Photoreal 2.0 / SDXL 变体）。PickScore 学到的既包含&quot;人类喜欢什么&quot;，也包含&quot;这几个模型的失败模式长什么样&quot;，两者在这个测试集上无法区分。作者自己在 §7 的相关工作讨论里已经点到类似的担忧（HPS 可能更对齐 StabilityAI Discord 那一小群用户），但没有把同样的质疑应用到自己身上。第二，评测协议里的平局阈值是<strong>逐模型在验证集上调出来的</strong>，而人类专家不享受这个待遇——他们直接被允许选平局。这在 70.5 与 68.0 这么小的差距下是一个不对称优势。第三，后续文献给出了 Pick-a-Pic prompt 分布的量化问题：HPS v2 的论文报告 Pick-a-Pic 中 <strong>34.9%</strong> 的样本其 prompt 重复出现超过 50 次，而这些重复 prompt 只占唯一 prompt 的 4.7%（文献已有结论，见 <a href="/notes/papers/2306.09341">2306.09341</a>）。作者用&quot;按 prompt 频率倒数加权&quot;在训练侧缓解了这个问题，但验证/测试的构造只保证 prompt 不跨划分重叠，并没有保证 prompt 分布本身有代表性。</p><p>论文为这个假设提供的最强证据是 Elo 相关性实验：它用的是 14,000 条真实用户偏好而非雇佣标注，覆盖 45 个模型配置。这确实比测试集准确率更有说服力。但它仍然来自同一个应用的同一批用户，所以它验证的是&quot;PickScore 在自己的分布内自洽&quot;，而不是&quot;PickScore 在分布外可信&quot;。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周之内能做的最小验证，目标是检验 §9 的第一条担忧——PickScore 的优势有多少来自&quot;认识这几个 backbone&quot;。</p><p><strong>数据</strong>：只用公开的 Pick-a-Pic 测试集（500 条）与 HPD v2 测试集（400 组、每组 9 张图）。不需要重训任何模型，PickScore 与 HPS v2 的权重都是公开的。</p><p><strong>实现</strong>：把 Pick-a-Pic 测试集按生成该图的 backbone 拆开，分成&quot;同 backbone 对比&quot;与&quot;跨 backbone 对比&quot;两个子集；分别算 PickScore 的加权准确率。再在 HPD v2 测试集上按模型对拆分，看 PickScore 在<strong>训练时没见过的模型对</strong>（HPD v2 测试集有 5 个训练集里没有的模型）上的准确率。</p><p><strong>测量</strong>：三个数字——Pick-a-Pic 同 backbone 准确率、Pick-a-Pic 跨 backbone 准确率、HPD v2 上分布外模型对的准确率。同时把随机基线与&quot;总是选美学分更高的那张&quot;这两个平凡基线一起报出来。</p><p><strong>判据</strong>：如果跨 backbone 准确率显著低于同 backbone，且 HPD v2 分布外模型对的准确率掉到接近平凡基线，那么&quot;PickScore 学到的主要是模型指纹而非人类偏好&quot;这一替代解释就得到支持。反过来，如果三个数字都稳定在 70 附近，§9 的担忧就被削弱。已知的参照点是：HPS v2 论文报告 PickScore 在 HPD v2 测试集上是 79.8，在 ImageReward 测试集上是 62.9——这个 17 点的落差本身就提示了分布敏感性。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是构造一个<strong>偏好与美学解耦</strong>的测试集，检验 PickScore 到底学到了什么。</p><p>具体做法：固定一个 backbone 与一个随机种子，只改 classifier-free guidance 尺度生成图像对。论文自己的 Fig. 3(a) 已经显示，在 Pick-a-Pic 的数据里 CFG=9 通常打败 CFG=3；论文的 Fig. 5 也承认高 CFG 的图&quot;更鲜艳、人更喜欢&quot;。那么问题来了：PickScore 的 70.5% 里，有多大比例只是学会了&quot;选更鲜艳、对比度更高的那张&quot;？</p><p>反例实验：取一批 prompt，各生成 CFG ∈ {3, 6, 9} 三张图，用一个纯低层图像统计量（比如饱和度均值 + 对比度）做一个<strong>没有任何语义理解</strong>的打分器，在 Pick-a-Pic 测试集上跑同样的加权准确率协议（含逐模型调平局阈值）。如果这个平凡打分器能拿到 63–66 左右，那么 PickScore 相对随机 56.8 的 13.7 个点里，很大一部分可以被&quot;鲜艳度检测&quot;这个替代解释吃掉，&quot;超人类&quot;的叙事就需要重写。论文里其实已经有一个指向这个方向的定性观察：作者在 Fig. 4 分析 CLIP-H 与 PickScore 的分歧时写道，PickScore 常常选更美观的图，&quot;有时以牺牲对 prompt 的忠实度为代价&quot;。</p><p>第二种攻击是可预测的失效场景：给定一个需要<strong>精确计数或空间关系</strong>的 prompt（&quot;三只狗&quot;、&quot;杯子在书的左边&quot;），构造一对图，其中 A 计数正确但略显朴素、B 计数错误但极其精美。按 PickScore 的行为模式它大概率选 B。这不是 bug——真实用户可能也选 B——但它意味着任何用 PickScore 做 headline 指标的对齐工作，都会系统性地把模型往&quot;好看但不一定对&quot;的方向推。DRaFT（<a href="/notes/papers/2309.17400">2309.17400</a>）中观察到的 reward hacking 与风格坍缩，可以视作这个预测的实证。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：本文把&quot;人类偏好&quot;当作一个标量来建模。但从数据本身就能看出这是过度压缩：人类专家只有 68.0 的一致性，作者也承认 PickScore 有时用 prompt 忠实度换美观度。一个 68% 一致的信号被压成一个数，剩下的 32% 分歧被当成噪声丢掉了，而这些分歧恰恰是&quot;不同人想要不同东西&quot;的地方。</p><p><strong>新的 framing</strong>：不训练一个标量评分函数，而训练一个<strong>偏好分歧的预测器</strong>——给定 prompt 与两张图，输出的不是&quot;哪张更好&quot;，而是&quot;人群会在这一对上分裂成什么形状&quot;。数据是现成的：HPD v2 的测试集每组由 10 个不同标注者独立标注（见 <a href="/notes/papers/2306.09341">2306.09341</a>），可以直接读出每一对的人群分歧度；Pick-a-Pic 虽然每对只有一个标注，但同一 prompt 下有大量来自不同用户的判断，可以聚合出 prompt 级的分歧统计。</p><p><strong>可借鉴的相邻领域工具</strong>：NLP 里的 annotator disagreement modeling 与 learning from noisy labels 已经有成熟做法（把标注者身份作为条件、显式建模标注者 confusion matrix）；推荐系统里的矩阵分解则给出了&quot;用户 × 物品&quot;低秩偏好的框架。把 PickScore 的单一 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">txt</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">img</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 内积换成&quot;用户嵌入 × 图像嵌入 × 文本嵌入&quot;的三阶交互，是一个直接的技术路径。</p><p><strong>第一个实验长什么样</strong>：在 HPD v2 测试集上，把每组 9 张图的 10 人标注拆成 5+5，用前 5 人拟合一个分歧预测器，在后 5 人上检验它能否预测出哪些图像对会引起分裂。评价指标是预测分歧度与真实分歧度的相关性，基线是&quot;用 PickScore 分数差的绝对值预测分歧&quot;——这是一个很强的平凡基线，HPS v2 的 Fig. 5 已经显示标注者一致性与 HPS v2 分数差呈明显正相关。如果新方法赢不过这个平凡基线，说明分歧确实可以被一个标量完全解释，那么本文的建模选择就是对的；如果赢了，就说明存在标量分数捕捉不到的、系统性的人群偏好结构，值得为它单独建一套对齐目标。</p>',66)])])}const d=a(e,[["render",l]]);export{h as __pageData,d as default};
